import Phaser from './phaser-lite.js'
import { DungeonScene } from './game/DungeonScene.js'
import { ARCHETYPES } from './game/content.js'

const initial={mode:'title',hp:1,maxHp:1,sanity:1,maxSanity:1,sanityState:'Stable',level:1,xp:0,nextXp:34,archetype:null,archetypeName:'',abilityName:'',abilityReady:true,passiveName:'',passiveDescription:'',guarded:false,log:['Choose an expedition profile to begin.'],enemy:null,dead:false,seed:'',floor:1,floorName:'The Drowned Observatory',objective:'Begin an expedition.',steps:0,position:'-',inventory:[],equippedWeaponId:null,equippedCharmId:null,hasSave:false,interaction:null,endingTitle:'',endingText:'',choices:[],journal:[],discovered:0,totalWalkable:0,audioEnabled:true,reducedMotion:false,secretCount:0,runStats:{kills:0,bossesDefeated:0,elitesDefeated:0,damageDealt:0,damageTaken:0,itemsUsed:0,retreats:0,rests:0}}
let state=structuredClone(initial), seed='', archetype='surveyor', tab='inventory', game=null
const root=document.getElementById('root')
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))
const pct=(v,m)=>Math.max(0,Math.min(100,v/Math.max(1,m)*100))
const stat=(label,v,m)=>`<div class="stat"><div class="stat-row"><span>${esc(label)}</span><strong>${v}/${m}</strong></div><div class="meter" role="progressbar" aria-label="${esc(label)}" aria-valuemin="0" aria-valuemax="${m}" aria-valuenow="${v}"><span style="width:${pct(v,m)}%"></span></div></div>`
function useful(item){if(item.kind!=='consumable')return true;return (!!item.heal&&state.hp<state.maxHp)||(!!item.restoreSanity&&item.restoreSanity>0&&state.sanity<state.maxSanity)}
function itemStats(i){const a=[];if(i.attackBonus)a.push(`ATK +${i.attackBonus}`);if(i.defenseBonus)a.push(`DEF +${i.defenseBonus}`);if(i.maxSanityBonus)a.push(`SAN MAX +${i.maxSanityBonus}`);if(i.critBonus)a.push(`CRIT +${Math.round(i.critBonus*100)}%`);if(i.sanityResist)a.push(`SAN RES ${Math.round(i.sanityResist*100)}%`);if(i.healOnKill)a.push(`KILL HEAL +${i.healOnKill}`);if(i.heal)a.push(`HEAL ${i.heal}`);if(i.restoreSanity)a.push(`SAN ${i.restoreSanity>0?'+':''}${i.restoreSanity}`);return a.join(' · ')}
function sanityCopy(s){return s==='Stable'?'The map, corridor and your senses broadly agree.':s==='Uneasy'?'Peripheral movement and distant sounds may not be trustworthy.':s==='Distorted'?'The dungeon can lie visually. Check assumptions before acting.':s==='Delirious'?'The minimap and silhouettes may be false.':'Certainty is gone. Zero sanity is dangerous, but not immediate death.'}

root.innerHTML=`<main class="shell"><header><div><p class="eyebrow">OPEN-SOURCE COSMIC DUNGEON CRAWLER</p><h1>Abyssal Descent</h1></div><span class="badge">FINAL · v1.0.1</span></header><section id="runbar" class="runbar"></section><section class="game-grid"><div class="viewport-card"><div id="game" class="game" role="img" aria-label="First-person dungeon view with minimap and encounter visuals"></div><section id="start-panel" class="start-panel"></section><div id="controls" class="controls"></div></div><aside id="sidebar"></aside></section><footer>Original open-source cosmic-horror dungeon crawler. Inspired by classic grid RPGs; no Cyclopean assets, text, code, characters or maps are used.</footer></main>`
const $=id=>document.getElementById(id)

function renderRunbar(){ $('runbar').innerHTML=`<div class="run-status"><span>${esc(state.floorName)}</span><strong>${state.mode==='title'?'Awaiting expedition':`Seed ${esc(state.seed)}`}</strong></div><button aria-pressed="${state.audioEnabled}" data-action="toggle-audio">${state.audioEnabled?'Audio on':'Audio off'}</button><button aria-pressed="${state.reducedMotion}" data-action="toggle-motion">${state.reducedMotion?'Motion reduced':'Motion full'}</button>${state.mode!=='title'?`<button data-action="save" ${state.dead?'disabled':''} title="${state.dead?'A lost expedition cannot overwrite the last valid checkpoint.':''}">Save</button>`:''}<button data-action="load" ${!state.hasSave?'disabled':''}>Load</button>${state.mode!=='title'?'<button data-action="title">Main menu</button>':''}` }
function renderStart(){
 const panel=$('start-panel'); const controls=$('controls');
 if(state.mode!=='title'){panel.hidden=true;controls.hidden=false;controls.innerHTML=`<button data-action="left" ${state.enemy||state.dead||state.mode==='ending'?'disabled':''}>↶ Turn</button><button data-action="forward" ${state.enemy||state.dead||state.mode==='ending'?'disabled':''}>↑ Forward</button><button data-action="right" ${state.enemy||state.dead||state.mode==='ending'?'disabled':''}>Turn ↷</button><button data-action="back" ${state.enemy||state.dead||state.mode==='ending'?'disabled':''}>↓ Back</button><button class="interact" data-action="interact" ${!state.interaction||state.enemy||state.dead||state.mode==='ending'?'disabled':''}>${state.interaction?`E · ${esc(state.interaction.label)}`:'E · Interact'}</button>`;return}
 controls.hidden=true;panel.hidden=false
 panel.innerHTML=`<div class="start-copy"><span class="kicker">EXPEDITION PROFILE</span><h2>Four acts. One descent. The map may stop telling the truth.</h2><p>Choose a specialist and a reproducible seed. Explore handcrafted anomalies inside procedural dungeons, survive phased guardians, and decide what waits beyond the Great Abyss.</p></div><div class="archetypes">${Object.entries(ARCHETYPES).map(([id,a])=>`<button class="archetype-card ${archetype===id?'selected':''}" aria-pressed="${archetype===id}" data-archetype="${id}"><strong>${esc(a.name)}</strong><span>${esc(a.blurb)}</span><small><b>${esc(a.abilityName)}</b> — ${esc(a.abilityDescription)}</small><small><b>${esc(a.passiveName)}</b> — ${esc(a.passiveDescription)}</small></button>`).join('')}</div><div class="seed-row"><label><span>Seed</span><input id="seed-input" value="${esc(seed)}" maxlength="48" placeholder="Leave blank for a random expedition"></label><button class="primary" data-start="1">Begin descent</button></div>${state.hasSave?'<button class="resume" data-action="load">Resume local expedition</button>':''}`
}
function renderSidebar(){const side=$('sidebar'); if(state.mode==='title'){side.innerHTML='';return} const explored=state.totalWalkable?Math.round(state.discovered/state.totalWalkable*100):0;const weapon=state.inventory.find(i=>i.instanceId===state.equippedWeaponId),charm=state.inventory.find(i=>i.instanceId===state.equippedCharmId)
 const enemyPanel=state.dead?`<div class="dead-actions"><p>Your last valid checkpoint remains available.</p><button data-action="load" ${!state.hasSave?'disabled':''}>Load save</button><button data-action="title">New expedition</button></div>`:state.enemy?`<p>${esc(state.enemy.description)}</p><p class="intent">Intent: ${esc(state.enemy.intent)}.</p>${stat(state.enemy.boss?'Guardian':'Enemy',state.enemy.hp,state.enemy.maxHp)}<div class="combat-actions"><button data-action="attack">F · Attack</button><button data-action="guard">G · Guard</button><button data-action="focus">R · Focus</button><button class="ability" data-action="ability" ${!state.abilityReady?'disabled':''}>Q · ${esc(state.abilityName)}</button><button data-action="flee" ${state.enemy.boss?'disabled':''}>X · Flee</button></div>`:'<p>WASD / arrows move. E interacts. In combat: F attack, G guard, R focus, Q ability, X flee. M toggles audio.</p>'
 const inventory=state.inventory.length?state.inventory.map(item=>{const eq=item.instanceId===state.equippedWeaponId||item.instanceId===state.equippedCharmId;const locked=state.dead||state.mode==='ending'||(item.kind!=='consumable'&&!!state.enemy)||(item.kind==='consumable'&&!useful(item));const title=state.dead?'A lost expedition cannot use or change inventory.':state.mode==='ending'?'The expedition is already at its final decision.':item.kind!=='consumable'&&state.enemy?'Equipment is locked during combat.':item.kind==='consumable'&&!useful(item)?'This consumable would provide no benefit right now.':'';return `<article class="item ${item.kind==='quest'?'quest-item':''} ${item.unique?'unique-item':''}"><div><strong>${esc(item.name)}${item.kind==='consumable'&&(item.quantity??1)>1?` ×${item.quantity}`:''}</strong><small>${esc(item.description)}</small>${itemStats(item)?`<em class="item-stats">${esc(itemStats(item))}</em>`:''}</div>${eq?'<span class="equipped">equipped</span>':item.kind==='quest'?'<span class="quest-tag">key item</span>':`<button data-action="${item.kind==='consumable'?'use':'equip'}:${esc(item.instanceId)}" ${locked?'disabled':''} title="${esc(title)}">${state.dead||state.mode==='ending'?'Locked':item.kind==='consumable'?(useful(item)?'Use':'Full'):state.enemy?'Locked':'Equip'}</button>`}</article>`}).join(''):'<p class="empty">Your pack is empty.</p>'
 const journal=[...state.journal].reverse().map((e,i)=>`<article>${esc(e)}</article>`).join('')
 const ending=state.mode==='ending'?`<section class="panel ending-panel"><span class="kicker">FINAL DECISION</span><h2>${esc(state.endingTitle)}</h2><p>${esc(state.endingText)}</p>${state.choices.length?`<div class="ending-choices">${state.choices.map(c=>`<button data-action="ending:${esc(c.id)}" ${c.disabled?'disabled':''}><strong>${esc(c.label)}</strong><span>${esc(c.description)}</span></button>`).join('')}</div>`:`<div class="run-summary">${[['Level',state.level],['Steps',state.steps],['Kills',state.runStats.kills],['Guardians',`${state.runStats.bossesDefeated}/4`],['Secrets',state.secretCount],['Act IV mapped',`${explored}%`],['Elites',state.runStats.elitesDefeated],['Items used',state.runStats.itemsUsed],['Retreats',state.runStats.retreats],['Refuges used',state.runStats.rests],['Damage dealt',state.runStats.damageDealt],['Damage taken',state.runStats.damageTaken]].map(([a,b])=>`<div><span>${a}</span><strong>${b}</strong></div>`).join('')}</div><button class="primary" data-action="title">Return to main menu</button>`}</section>`:''
 side.innerHTML=`<section class="panel objective-panel"><div class="panel-title"><h2>Objective</h2><span>ACT ${state.floor}</span></div><p class="objective">${esc(state.objective)}</p>${state.interaction?`<div class="context-hint"><strong>${esc(state.interaction.label)}</strong><span>${esc(state.interaction.hint)}</span></div>`:''}</section><section class="panel stats"><div class="panel-title"><h2>${esc(state.archetypeName)} · Lv ${state.level}</h2><span>${state.steps} steps · ${explored}% mapped</span></div>${stat('Vitality',state.hp,state.maxHp)}${stat(`Sanity · ${state.sanityState}`,state.sanity,state.maxSanity)}${stat('Experience',state.xp,state.nextXp)}<div class="sanity-readout ${state.sanityState.toLowerCase()}"><strong>${esc(state.sanityState)}</strong><span>${esc(sanityCopy(state.sanityState))}</span></div><dl class="loadout"><div><dt>Weapon</dt><dd>${esc(weapon?.name??'None')}</dd></div><div><dt>Charm</dt><dd>${esc(charm?.name??'None')}</dd></div><div><dt>Ability</dt><dd>${esc(state.abilityName)} ${state.abilityReady?'✓':'…'}</dd></div><div><dt>Passive</dt><dd title="${esc(state.passiveDescription)}">${esc(state.passiveName)}</dd></div><div><dt>Secrets</dt><dd>${state.secretCount}</dd></div></dl></section><section class="panel enemy-panel ${state.enemy?.boss?'boss-panel':''}"><div class="panel-title"><h2>${esc(state.enemy?state.enemy.name:state.dead?'Expedition lost':'The corridor')}</h2>${state.enemy?.boss?`<span>PHASE ${state.enemy.phase}/${state.enemy.maxPhase}</span>`:''}</div>${enemyPanel}</section>${ending}<section class="panel collection-panel"><div class="tabs"><button class="${tab==='inventory'?'active':''}" aria-pressed="${tab==='inventory'}" data-tab="inventory">Inventory</button><button class="${tab==='journal'?'active':''}" aria-pressed="${tab==='journal'}" data-tab="journal">Journal · ${state.journal.length}</button></div>${tab==='inventory'?`<div class="inventory">${inventory}</div>`:`<div class="journal">${journal}</div>`}</section><section class="panel log-panel" aria-live="polite"><div class="panel-title"><h2>Field notes</h2><span>latest first</span></div><ol>${state.log.slice(-10).reverse().map((line,i)=>`<li>${esc(line)}</li>`).join('')}</ol></section>`
}
function render(){renderRunbar();renderStart();renderSidebar()}
function send(action){game?.events.emit('ui-action',action)}
root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.archetype){archetype=b.dataset.archetype;renderStart();return}if(b.dataset.tab){tab=b.dataset.tab;renderSidebar();return}if(b.dataset.start){const s=seed.trim()||`ABYSS-${Date.now().toString(36).toUpperCase()}`;send(`start:${archetype}:${encodeURIComponent(s)}`);return}if(b.dataset.action)send(b.dataset.action)})
root.addEventListener('input',e=>{if(e.target.id==='seed-input')seed=e.target.value})
window.addEventListener('abyssal-runtime-error',e=>showBootError(e.detail))
function showBootError(err){const box=document.createElement('section');box.className='boot-error';box.innerHTML=`<h1>Runtime error</h1><p>The game could not continue. This build shows the error instead of leaving a black screen.</p><code>${esc(err?.stack||err?.message||err)}</code>`;document.body.prepend(box)}
render()
try{
 game=new Phaser.Game({type:Phaser.AUTO,parent:$('game'),width:800,height:500,backgroundColor:'#070a08',pixelArt:true,scene:[DungeonScene],scale:{mode:Phaser.Scale.FIT,autoCenter:Phaser.Scale.CENTER_BOTH}})
 game.events.on('snapshot',snapshot=>{state=snapshot;if(snapshot.seed)seed=snapshot.seed;if(snapshot.archetype)archetype=snapshot.archetype;render()})
 window.__abyssal={send,getState:()=>structuredClone(state),getGame:()=>game}
}catch(err){showBootError(err)}
